import java.util.*;

class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        // Build adjacency list: city -> list of (neighbor, time)
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(new int[]{e[1], e[2]});
            graph[e[1]].add(new int[]{e[0], e[2]});
        }

        // dist[node][time] = minimum cost to reach node using exactly time minutes
        // We only need to track the minimum cost to reach node within time <= maxTime.
        // To optimize memory, we keep for each node the minimum cost for each time.
        // We'll use a priority queue to do a Dijkstra-like search on (cost, time, node).
        // State: (cost, time, node)
        // We want to minimize cost with time <= maxTime.

        // Initialize dist array with large values
        int[][] dist = new int[n][maxTime + 1];
        for (int i = 0; i < n; i++) Arrays.fill(dist[i], Integer.MAX_VALUE);
        dist[0][0] = passingFees[0];

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        // cost, time, node
        pq.offer(new int[]{passingFees[0], 0, 0});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int cost = cur[0], time = cur[1], node = cur[2];
            if (node == n - 1) return cost;
            if (cost > dist[node][time]) continue;

            for (int[] nxt : graph[node]) {
                int nextNode = nxt[0], t = nxt[1];
                int nextTime = time + t;
                if (nextTime > maxTime) continue;
                int nextCost = cost + passingFees[nextNode];
                if (nextCost < dist[nextNode][nextTime]) {
                    dist[nextNode][nextTime] = nextCost;
                    pq.offer(new int[]{nextCost, nextTime, nextNode});
                }
            }
        }

        return -1;
    }
}

